     1|/**
     2| * Passwordless owner sign-in.
     3| *
     4| * POST /api/ivx/owner-passwordless-login
     5| *   body: { email }
     6| *
     7| * The owner types ONLY their email. The backend:
     8| *   1. Validates the email is in the owner allowlist
     9| *      (IVX_OWNER_REGISTRATION_EMAILS / IVX_BASELINE_OWNER_EMAILS).
    10| *   2. Uses the Supabase admin (service-role) client to find the owner auth user
    11| *      (creating + confirming them if they do not exist yet).
    12| *   3. PRESERVES the owner's password: mints the session with a server-side
    13| *      magic-link token (admin generateLink + verifyOtp token_hash). The
    14| *      owner's manual password is NEVER modified by this flow anymore.
    15| *      (The previous behavior reset the password on every call, which kept
    16| *      breaking the owner's manual email+password sign-in.)
    17| *   4. Falls back to the legacy password self-heal ONLY if the magic-link
    18| *      session mint fails, so owner access can never be fully locked out.
    19| *
    20| * No password is ever sent back to the client. The client installs the
    21| * returned session via supabase.auth.setSession(), which produces a real
    22| * Supabase session — so owner-AI chat approval (allowlist + bearer check)
    23| * works automatically.
    24| */
    25|import { randomBytes } from 'node:crypto';
    26|import { createClient, type SupabaseClient } from '@supabase/supabase-js';
    27|import { ownerOnlyJson, ownerOnlyOptions } from './owner-only';
    28|import { getIVXOwnerEmailAllowlist } from '../../expo/shared/ivx/access-control';
    29|
    30|const DEPLOYMENT_MARKER = 'ivx-owner-passwordless-login-password-preserving-2026-07-17';
    31|
    32|const PASSWORDLESS_HEADERS = {
    33|  'Content-Type': 'application/json',
    34|  'Cache-Control': 'no-store',
    35|  'Access-Control-Allow-Origin': 'https://ivxholding.com',
    36|  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
    37|  'Access-Control-Allow-Methods': 'POST, OPTIONS',
    38|} as const;
    39|
    40|function readTrimmed(value: unknown): string {
    41|  return typeof value === 'string' ? value.trim() : '';
    42|}
    43|
    44|function sanitizeEmail(value: unknown): string {
    45|  return readTrimmed(value).toLowerCase();
    46|}
    47|
    48|function isValidEmail(email: string): boolean {
    49|  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    50|}
    51|
    52|function nowIso(): string {
    53|  return new Date().toISOString();
    54|}
    55|
    56|/** Generate a cryptographically random password (only used when creating a brand-new auth user or in the legacy fallback). */
    57|function generateRandomPassword(): string {
    58|  return randomBytes(32).toString('base64url') + '!A1';
    59|}
    60|
    61|function readEnv(name: string): string {
    62|  return (process.env[name] ?? '').trim();
    63|}
    64|
    65|function resolveSupabaseUrl(): string {
    66|  return readEnv('EXPO_PUBLIC_SUPABASE_URL') || readEnv('SUPABASE_URL');
    67|}
    68|
    69|function resolveServiceRoleKey(): string {
    70|  return readEnv('SUPABASE_SERVICE_ROLE_KEY') || readEnv('SUPABASE_SERVICE_KEY');
    71|}
    72|
    73|function resolveAnonKey(): string {
    74|  return readEnv('EXPO_PUBLIC_SUPABASE_ANON_KEY');
    75|}
    76|
    77|function createAdminClient() {
    78|  const supabaseUrl = resolveSupabaseUrl();
    79|  const serviceRoleKey = resolveServiceRoleKey();
    80|  if (!supabaseUrl) {
    81|    throw new Error('Supabase URL is not configured on the backend (EXPO_PUBLIC_SUPABASE_URL).');
    82|  }
    83|  if (!serviceRoleKey) {
    84|    throw new Error('Supabase service role key is not configured on the backend (SUPABASE_SERVICE_ROLE_KEY).');
    85|  }
    86|  return createClient(supabaseUrl, serviceRoleKey, {
    87|    auth: { autoRefreshToken: false, persistSession: false },
    88|  });
    89|}
    90|
    91|type OwnerSessionResponse = {
    92|  success: true;
    93|  accessToken: string;
    94|  refreshToken: string;
    95|  expiresAt: number;
    96|  expiresAtIso: string;
    97|  userId: string;
    98|  email: string;
    99|  /** Always false on the primary path now — the owner password is preserved. */
   100|  passwordSelfHealed: boolean;
   101|  /** True when the owner's manual password was NOT modified by this login. */
   102|  passwordPreserved: boolean;
   103|  /** 'magiclink_token_hash' (primary, password untouched) or 'legacy_password_self_heal' (fallback). */
   104|  sessionMethod: string;
   105|  authUserCreated: boolean;
   106|  deploymentMarker: string;
   107|  timestamp: string;
   108|};
   109|
   110|type OwnerSessionFailure = {
   111|  success: false;
   112|  message: string;
   113|  rootCause: string;
   114|  deploymentMarker: string;
   115|  timestamp: string;
   116|};
   117|
   118|type MintedSession = {
   119|  accessToken: string;
   120|  refreshToken: string;
   121|  expiresAt: number;
   122|};
   123|
   124|/**
   125| * Mint a real Supabase session WITHOUT touching the owner's password:
   126| * admin generateLink(magiclink) -> verifyOtp(token_hash) with the anon key.
   127| */
   128|async function mintSessionViaMagicLink(
   129|  adminClient: SupabaseClient,
   130|  email: string,
   131|): Promise<{ ok: boolean; session?: MintedSession; errorMessage?: string }> {
   132|  const supabaseUrl = resolveSupabaseUrl();
   133|  const anonKey = resolveAnonKey();
   134|  if (!anonKey) {
   135|    return { ok: false, errorMessage: 'Supabase anon key is not configured on the backend.' };
   136|  }
   137|
   138|  let tokenHash = '';
   139|  try {
   140|    const { data, error } = await adminClient.auth.admin.generateLink({ type: 'magiclink', email });
   141|    if (error) {
   142|      return { ok: false, errorMessage: `generateLink failed: ${error.message}` };
   143|    }
   144|    const properties = data?.properties as { hashed_token?: string } | null | undefined;
   145|    tokenHash = typeof properties?.hashed_token === 'string' ? properties.hashed_token : '';
   146|    if (!tokenHash) {
   147|      return { ok: false, errorMessage: 'generateLink did not return a hashed_token.' };
   148|    }
   149|  } catch (error) {
   150|    return { ok: false, errorMessage: error instanceof Error ? error.message : 'generateLink threw.' };
   151|  }
   152|
   153|  try {
   154|    const anonClient = createClient(supabaseUrl, anonKey, {
   155|      auth: { autoRefreshToken: false, persistSession: false },
   156|    });
   157|    const { data, error } = await anonClient.auth.verifyOtp({ type: 'magiclink', token_hash: tokenHash });
   158|    if (error) {
   159|      return { ok: false, errorMessage: `verifyOtp failed: ${error.message}` };
   160|    }
   161|    const session = data?.session;
   162|    const accessToken = typeof session?.access_token === 'string' ? session.access_token : '';
   163|    const refreshToken = typeof session?.refresh_token === 'string' ? session.refresh_token : '';
   164|    const expiresAt = typeof session?.expires_at === 'number' ? session.expires_at : 0;
   165|    if (!accessToken || !refreshToken) {
   166|      return { ok: false, errorMessage: 'verifyOtp did not return access_token/refresh_token.' };
   167|    }
   168|    return { ok: true, session: { accessToken, refreshToken, expiresAt } };
   169|  } catch (error) {
   170|    return { ok: false, errorMessage: error instanceof Error ? error.message : 'verifyOtp threw.' };
   171|  }
