   174|/** Server-side password grant against the Supabase Auth token endpoint (legacy fallback only). */
   175|async function passwordGrant(supabaseUrl: string, email: string, password: string): Promise<{
   176|  ok: boolean;
   177|  accessToken?: string;
   178|  refreshToken?: string;
   179|  expiresAt?: number;
   180|  errorMessage?: string;
   181|  errorStatus?: number;
