   197|      },
   198|      body: JSON.stringify({ email, password }),
   199|      signal: controller.signal,
   200|    });
   201|    const text = await response.text();
   202|    let parsed: Record<string, unknown> = {};
   203|    try {
   204|      parsed = text ? (JSON.parse(text) as Record<string, unknown>) : {};
   205|    } catch {
   206|      return { ok: false, errorMessage: `Supabase returned non-JSON auth response (HTTP ${response.status}).` };
   207|    }
   208|    if (!response.ok) {
   209|      const message = typeof parsed.error_description === 'string'
   210|        ? parsed.error_description
   211|        : typeof parsed.msg === 'string'
   212|          ? parsed.msg
   213|          : typeof parsed.error === 'string'
   214|            ? parsed.error
   215|            : `Supabase rejected the password grant (HTTP ${response.status}).`;
   216|      return { ok: false, errorMessage: message, errorStatus: response.status };
   217|    }
   218|    const accessToken = typeof parsed.access_token === 'string' ? parsed.access_token : '';
   219|    const refreshToken = typeof parsed.refresh_token === 'string' ? parsed.refresh_token : '';
   220|    const expiresAt = typeof parsed.expires_at === 'number' ? parsed.expires_at : 0;
