     1|/**
     2| * IVX AI Provider State Machine
     3| *
     4| * Replaces the broken retry loop that repeatedly tried the same expired
     5| * credential against multiple endpoints. This module enforces:
     6| *
     7| *   1. Validate provider once at startup.
     8| *   2. Mark invalid provider as unavailable after a confirmed 401/403.
     9| *   3. Never retry the same expired key (within the recovery cooldown).
    10| *   4. Maximum one controlled fallback attempt (with a DIFFERENT key).
    11| *   5. Return one clear failure with trace ID if all approved providers fail.
    12| *   6. Never loop endlessly through providers.
    13| *   7. Never expose credential values.
    14| *   8. RECOVERY (2026-07-18 emergency repair): failure states are NOT permanent.
    15| *      A latched PROVIDER_FAILED / AI_UNAVAILABLE state re-opens to a single
    16| *      half-open probe after IVX_AI_PROVIDER_RECOVERY_COOLDOWN_MS (default 60s),
    17| *      so a transient outage or a since-rotated credential can never brick the
    18| *      runtime until reboot. Root cause of the 2026-07-18 production outage:
    19| *      markAIUnavailable() latched permanently while the loaded key was valid.
    20| *
    21| * States:
    22| *   PROVIDER_VALIDATING → PROVIDER_READY | PROVIDER_FAILED
    23| *   FALLBACK_VALIDATING → FALLBACK_READY | AI_UNAVAILABLE
    24| */
    25|
    26|export type IVXProviderState =
    27|  | 'PROVIDER_VALIDATING'
    28|  | 'PROVIDER_READY'
    29|  | 'PROVIDER_FAILED'
    30|  | 'FALLBACK_VALIDATING'
    31|  | 'FALLBACK_READY'
    32|  | 'AI_UNAVAILABLE';
    33|
    34|export type IVXProviderHealth = {
    35|  state: IVXProviderState;
    36|  provider: string;
    37|  model: string;
    38|  adapterVersion: string;
    39|  credentialLoaded: boolean;
    40|  credentialValid: boolean;
    41|  lastValidationTime: string | null;
    42|  lastHttpStatus: number | null;
    43|  fallbackEnabled: boolean;
    44|  fallbackUsed: boolean;
    45|  traceId: string | null;
    46|  error: string | null;
    47|};
    48|
    49|const state: IVXProviderHealth = {
    50|  state: 'PROVIDER_VALIDATING',
    51|  provider: 'unknown',
    52|  model: 'unknown',
    53|  adapterVersion: 'unknown',
    54|  credentialLoaded: false,
    55|  credentialValid: false,
    56|  lastValidationTime: null,
    57|  lastHttpStatus: null,
    58|  fallbackEnabled: false,
    59|  fallbackUsed: false,
    60|  traceId: null,
    61|  error: null,
    62|};
    63|
    64|/** Wall-clock ms when the current failure state was latched. Null when healthy. */
    65|let failureLatchedAtMs: number | null = null;
    66|
    67|const RECOVERY_COOLDOWN_MS = (() => {
    68|  const raw = Number.parseInt(
    69|    typeof process.env.IVX_AI_PROVIDER_RECOVERY_COOLDOWN_MS === 'string'
    70|      ? process.env.IVX_AI_PROVIDER_RECOVERY_COOLDOWN_MS.trim()
    71|      : '',
    72|    10,
    73|  );
    74|  return Number.isFinite(raw) && raw > 0 ? raw : 60_000;
    75|})();
    76|
    77|let cachedAdapterVersion: string | null = null;
    78|
    79|function getAdapterVersion(): string {
    80|  if (cachedAdapterVersion) return cachedAdapterVersion;
    81|  try {
    82|    // eslint-disable-next-line @typescript-eslint/no-require-imports
    83|    const pkg = require('@ai-sdk/openai/package.json');
    84|    cachedAdapterVersion = typeof pkg?.version === 'string' ? pkg.version : 'unknown';
    85|  } catch {
    86|    cachedAdapterVersion = 'unknown';
